/* 【2026-10-08】17729 卡佩里尼：推进轴心依次链。
 * 每个国家在己方弃牌堆随机抽 1 张，检视后由 resolve_italy_chain 处置。
 * 某国弃牌堆为空则跳过；全部处理完则清空 game.italy_chain。 */
function advance_italy_chain(game) {
	const ch = game.delegate
	if (!ch) return
	/*
	 * 【2026-10-22 修复·17729 "置于牌堆顶 / 留在弃牌堆"点了没反应】
	 * 上一张打出的牌可能开出响应窗口（如 德国《发起陆战》消灭苏军 ->
	 * 17831 的 piece_removed 等同盟国表态）。action 入口此时会挡下一切非响应动作，
	 * 但旧实现照样抽下一张牌并让当前国"处置" —— 客户端 17729 选择框还在，
	 * 点置顶/弃置全被服务端静默拒绝，表现为卡死。
	 * 这里改为挂起：调用方已清空 pickedNation/pickedCard（框会自动隐藏），
	 * 等响应栈清空后由 response_reconcile_active -> resume_italy_chain 续跑。
	 */
	if ((game.response_stack && game.response_stack.length) ||
		(game.response_queue && game.response_queue.length)) {
		ch.waiting_response = true
		game.log.push('【卡佩里尼】等待响应结算后继续处置')
		return
	}
	ch.waiting_response = false
	while (ch.step < ch.order.length) {
		const nat = ch.order[ch.step]
		const dis = game.discard[nat] || []
		if (!dis.length) {
			ch.results.push({ nation: nat, card: null, choice: 'empty' })
			ch.step++
			continue
		}
		const cid = dis[Math.floor(Math.random() * dis.length)]
		ch.pickedNation = nat
		ch.pickedCard = cid
		ch.sub = null
		game.current_nation = nat
		const c = inst_card(String(inst_card_id(cid)))
		/*
		 * 【2026-10-26 保密】从【弃牌堆】随机抽到的那张牌仍属暗区信息，
		 * 写卡名等于把该国弃牌堆摊开。本方要处置哪张由 view 下发（客户端看得见），
		 * 公共日志只说"抽到 1 张牌"。
		 */
		game.log.push('【' + nat + '】因《卡佩里尼》从弃牌堆随机抽到 1 张牌，请处置')
		return
	}
	/*
	 * 【2026-10-27 玩家口径】链结束输出【汇总】：每个国家抽到什么、怎么处置。
	 * 单条处置日志已经带卡名（见 resolve_italy_chain），这里再汇总一次便于复盘。
	 * 注意：finish_delegate 会清掉 game.delegate，必须先取 results。
	 */
	{
		const rows = []
		for (const r of (ch.results || [])) {
			if (!r.card) {
				rows.push(r.nation + '：弃牌堆为空（跳过）')
				continue
			}
			const c = inst_card(String(inst_card_id(r.card)))
			const nm = c ? c.name : String(r.card)
			const how = r.choice === 'play' ? '打出'
				: (r.choice === 'decktop' ? '置于牌堆顶'
					: (r.choice === 'discard' ? '留在弃牌堆' : (r.choice || '?')))
			rows.push(r.nation + '：《' + nm + '》→ ' + how)
		}
		if (rows.length) game.log.push('【卡佩里尼】处置结果：' + rows.join('；'))
	}
	finish_delegate(game, game.delegate)
	game.log.push('【卡佩里尼】所有友方玩家处置完毕')
}

/* 【2026-10-22】响应窗口清空后，续跑被它挂起的 17729 卡佩里尼链。
 * 只在"栈/队列确实已空且没有挂起战斗"时推进，避免与空军代受 / 延期响应抢序。 */
function resume_italy_chain(game) {
	const ch = game.delegate
	if (!ch || ch.mode !== 'order' || !ch.waiting_response) return
	if ((game.response_stack && game.response_stack.length) ||
		(game.response_queue && game.response_queue.length)) return
	if (game.pending_battle || (game.battle_in_progress || 0)) return
	ch.waiting_response = false
	advance_italy_chain(game)
	refresh(game)
}

/* ============================================================
 * 8 张增强卡（ECHO / ↑）的效果配置 —— 2026-09-25 实现
 *
 * 【必须放在 EVENT_EFFECTS 之后】
 * 因为要调用 space_ids_of()，而它依赖 const PLACE_ALIAS ——
 * const 有 TDZ，放在前面会抛
 * "Cannot access 'PLACE_ALIAS' before initialization"。
 *
 * 卡面文本由【GLM 读图核对】（2026-09-25），OCR 原文全部有误已更正。
 * 时点声明见 CARD_TRIGGERS：
 *   玩家 2026-09-25 明确"所有涉及阶段的时机都是【自己】回合"。
 *
 * 与 EVENT 共用同一套执行器与 step 结构（见 card_effect_of），
 * 差别只在时点：增强卡在对应阶段打出，【不占】出牌名额。
 * ============================================================ */

/* ============================================================
 * 【2026-10-18】英国增强卡共享候选 helper
 * （模块顶层函数声明会提升，故 ECHO_EFFECTS 内的 15350 / 15355 可直接调用）
 * ============================================================ */

/* 15350《奇袭塔兰托》前提：<地中海>或其相邻地区存在英国飞机 */
function uk_air_near_med(game) {
	const med = data.id_of('地中海')
	if (med == null) return false
	const myF = faction_of_nation('英国')
	const near = [med].concat(get_connections(game, med, myF).map(Number))
	for (const p in game.piece_nation) {
		if (game.location[p] == null) continue
		if (game.piece_nation[p] !== '英国' || game.piece_type[p] !== 'air') continue
		if (near.indexOf(Number(game.location[p])) >= 0) return true
	}
	return false
}

/* 15355 候选：与某支【补给中】英国空军相邻的敌方空军。
 * ⚠ 不含同格 —— seize_air 要求发起机位于目标格的邻居（get_connections 不含自身）。 */
function uk_sas_air_targets(game) {
	const myF = faction_of_nation('英国')
	const sup = compute_supply(game)
	const out = []
	for (const p in game.piece_nation) {
		if (game.location[p] == null) continue
		if (game.piece_nation[p] !== '英国' || game.piece_type[p] !== 'air') continue
		if (!sup.in_supply[p]) continue
		const loc = Number(game.location[p])
		for (const sp of get_connections(game, loc, myF).map(Number)) {
			for (const q of pieces_on(game, sp)) {
				if (game.piece_type[q] !== 'air') continue
				const qf = faction_of_nation(game.piece_nation[q])
				if (!qf || qf === myF) continue
				if (out.indexOf(String(q)) < 0) out.push(String(q))
			}
		}
	}
	return out
}

/* 15355：为一支敌方空军挑发起的英国空军（须邻格 + 补给中） */
function uk_sas_initiator(game, target) {
	const myF = faction_of_nation('英国')
	const sp = Number(game.location[target])
	const sup = compute_supply(game)
	for (const p in game.piece_nation) {
		if (game.location[p] == null) continue
		if (game.piece_nation[p] !== '英国' || game.piece_type[p] !== 'air') continue
		if (!sup.in_supply[p]) continue
		const loc = Number(game.location[p])
		if (loc === sp) continue
		if (get_connections(game, loc, myF).map(Number).indexOf(sp) >= 0) return p
	}
	return null
}

