	'15430': (game, side, ctx, choice, extra) => {
		/* 日本发起海战后：① 选海域发起海战；② 选陆地发起陆战。两步分步结算。
		 * 海战发动后，陆战步以续打（defer）suspended，让【海战后的响应】
		 * （如 15426《驱逐舰运输》，作为独立响应卡在响应时点自动触发）先结算；
		 * 队列清空后由 promote_deferred_response 自动恢复（栈模型下即压回栈帧），
		 * 玩家再选陆战地区。
		 * 【2026-10-19 简化】删除原 transport 步及内嵌 15426 的 runTX/buildCont/
		 * landCont/optCont、手写 defer 分支、newResp 签名对比、清队列拷贝 hack ——
		 * 海战后的响应本就由触发层（request_responses）调度，15430 不再内嵌 15426。 */
		const emitLand2 = (seaId, descPrefix, defer) => {
			/*
			 * 【2026-10-26 修复】卡面「发起 1 次陆战」没有"相邻"限定 ——
			 * 候选改为【全图】日本能发起陆战的地区，不再只给"奇袭海战那一格的相邻陆地"。
			 */
			const cands = space_candidates_view(game, '日本', { op: 'battle', kind: 'land' })
			if (!cands.length)
				return { ok: true, desc: (descPrefix || '海战已结算') + '（全图无可发起陆战的地区，跳过陆战）' }
			const prompt = (descPrefix || '海战已结算') + '；选择要发起陆战的地区（任意）'
			if (defer) {
				/*
				 * 【栈重构·第二期】不再手写 deferred_response_choice 兼容壳；
				 * 直接返回 {defer:true}，由 trigger/resolve 的 defer 分支统一收编进
				 * game.deferred_response_stack（纯栈）。
				 */
				return { defer: true, kind: 'space', candidates: cands, prompt, extra: { step: 'land', seaId } }
			}
			return { pending: true, kind: 'space', candidates: cands, prompt, extra: { step: 'land', seaId } }
		}
		if (choice === undefined) {
			/*
			 * ① 选海域发起海战 —— 卡面「发起 1 次海战」无"相邻"限定：
			 * 候选是【全图】日本能发起海战的海域（不限于 ctx.space 及其相邻）。
			 */
			const cands = space_candidates_view(game, '日本', { op: 'battle', kind: 'sea' })
			if (!cands.length)
				return { ok: false, desc: '（全图无可发起海战的海域）' }
			return {
				pending: true, kind: 'space', candidates: cands,
				prompt: '选择要发起海战的海域（任意，只要日本能发起）',
				extra: { step: 'sea' },
			}
		}
		if (extra && extra.step === 'sea') {
			/* ② 已选海战地区：开海战 */
			const seaId = Number(choice)
			const sr = do_sea_battle_at(game, seaId, '日本')
			/* 海战未真正发动（无相邻补给日本海军）：直接陆战（无海战后响应要等） */
			if (!sr.ok)
				return emitLand2(seaId, sr.desc || '海战未发动', false)
			/* 海战发动：陆战步 suspended（defer），让海战后响应（如 15426）先结算 */
			return emitLand2(seaId, (sr.desc || '海战已结算'), true)
		}
		/* ③ 已选陆战地区：开陆战（extra.step === 'land'） */
		const lr = do_land_battle_at(game, Number(choice), '日本')
		return { ok: lr.ok, desc: lr.desc }
	},
